93	/** One step of a parent walk: the node, whatever the caller read, and its parent. */
94	export interface ParentHop<T> {
95	  number: number;
96	  /** What the caller's `read` returned for this node. */
97	  data: T;
98	  /** This node's own parent lookup, so a caller can tell a root from a failed read. */
99	  parent: ParentIssue;
100	}
