102	/**
103	 * Walk up a parent chain, oldest ancestor last, at most `MAX_PARENT_HOPS` deep.
104	 *
105	 * The one walker, because the loop it replaces was written twice and the two copies
106	 * disagreed about how far to go. `read` is the caller's, and it returns both the data
107	 * the caller wants for a node and that node's parent — one lookup per node, because
108	 * the caller needs the same read to decide whether to stop and to find the next edge.
109	 *
110	 * The edge differs by node kind: an issue's parent is GitHub's own sub-issue link,
111	 * while a pull request's is the `atomaton:parent-issue` tag. See
112	 * `adapters/github/tags.ts` for why that asymmetry is measured rather than accidental.
113	 *
114	 * Stops on a cycle, on a root (`parent: 0`), and on a lookup that failed
115	 * (`known: false`) — the last of which the caller can tell apart from a root, which
116	 * is the distinction `ParentIssue` exists for.
117	 */
118	export function* parentChain<T>(
119	  start: number,
120	  read: (current: number) => { data: T; parent: ParentIssue },
121	  maxHops: number = MAX_PARENT_HOPS,
122	): Generator<ParentHop<T>> {
123	  const visited = new Set<number>();
124	  let current = start;
125	  for (let hop = 0; hop < maxHops; hop++) {
126	    if (visited.has(current)) return;
127	    visited.add(current);
128	    const { data, parent } = read(current);
129	    yield { number: current, data, parent };
130	    if (!parent.known || parent.parent === 0) return;
131	    current = parent.parent;
132	  }
133	}

